problems.solution:
def sqdist(a, b):
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def assign(points, centres):
    labels = []
    for p in points:
        labels.append(min(range(len(centres)), key=lambda j: sqdist(p, centres[j])))
    return labels

def update(points, labels, k):
    centres = []
    for j in range(k):
        members = [p for p, l in zip(points, labels) if l == j]
        if not members:
            centres.append([0.0, 0.0])
        else:
            centres.append([sum(p[0] for p in members) / len(members), sum(p[1] for p in members) / len(members)])
    return centres
